JS=r'''
const gallery=[...document.querySelectorAll('[data-enlarge]')];const dialog=document.querySelector('dialog');let index=0,opener=null;const full=dialog.querySelector('img');const label=dialog.querySelector('.modal-title');const meta=dialog.querySelector('.modal-meta');const zoom=dialog.querySelector('[data-zoom]');
function show(i){index=(i+gallery.length)%gallery.length;const b=gallery[index],im=b.querySelector('img');full.src=im.getAttribute('src');full.alt=im.alt;full.width=Number(im.dataset.nativeWidth);full.height=Number(im.dataset.nativeHeight);label.textContent=b.dataset.title;meta.textContent=b.dataset.meta;dialog.classList.remove('zoomed');zoom.textContent='100% / detail';zoom.setAttribute('aria-pressed','false');}
gallery.forEach((b,i)=>b.addEventListener('click',()=>{opener=b;show(i);dialog.showModal();dialog.querySelector('[data-close]').focus();}));dialog.querySelector('[data-close]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-prev]').addEventListener('click',()=>show(index-1));dialog.querySelector('[data-next]').addEventListener('click',()=>show(index+1));zoom.addEventListener('click',()=>{const on=dialog.classList.toggle('zoomed');zoom.textContent=on?'Fit photograph':'100% / detail';zoom.setAttribute('aria-pressed',String(on));});dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();show(index-1);}if(e.key==='ArrowRight'){e.preventDefault();show(index+1);}});document.querySelector('[data-print]').addEventListener('click',()=>window.print());
'''
def render(portable=False):
 def url(a):
  p=ROOT/a['path']
  if portable:return 'data:'+(mimetypes.guess_type(p.name)[0] or 'application/octet-stream')+';base64,'+base64.b64encode(p.read_bytes()).decode()
  return os.path.relpath(p,OUT)
 def figure(a,original=False):
  state=a['status'];cls='rejected' if state=='REJECTED' else 'pending' if state in ('UNAPPROVED V2','UNREVIEWED') else '';title=f"{a['sourceIdentity']} · {a['version']} · {a['label']} · {state}";meta=f"{a['width']}×{a['height']} {a['mode']} · SHA256 {a['sha256']} · {a['path']}"
  return f'''<figure class="{'original' if original else 'study'}" data-image-status="{esc(state)}"><div class="figure-top"><span class="view-label">{esc(a['label'])}</span><span class="status {cls}">{esc(state)}</span></div><button class="image-button" data-enlarge data-title="{esc(title)}" data-meta="{esc(meta)}" aria-label="Enlarge {esc(title)}"><img src="{url(a)}" alt="{esc(title)}" loading="lazy" decoding="async" width="{a['width']}" height="{a['height']}" data-native-width="{a['width']}" data-native-height="{a['height']}" data-asset-index="{a['index']}"></button><figcaption>{'Unchanged historical file. Click for fabric and construction detail.' if original else 'Preserved photograph. Click to inspect at its genuine native size.'}<details><summary>File / dimensions / provenance</summary><p class="meta">{esc(a['path'])}<br>{a['width']} × {a['height']} px · {a['mode']} · SHA256 {a['sha256']}<br>No file bytes, colour or proportions changed for this board.</p></details></figcaption></figure>'''
 nav=''.join(f'<a href="#{sid}" title="{esc(NOTES[sid]["title"])}">{i:02d} / {esc(sid.replace("swimwear-ref-","SW ").replace("evening-ref-","OC ").replace("activewear-ref-","AC "))}</a>' for i,sid in enumerate(IDS,1))
 parts=[f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>ABERBACH — Womenswear art direction review</title><style>{fonts}{CSS}</style></head><body><div class="wrap"><header class="mast"><div class="brand">ABERBACH</div><div class="micro">Owner review · 23 October 2026<br>Womenswear / art direction reset</div></header><section class="hero"><div><h1>Womenswear.<br>Art direction review.</h1><p>Nine unfinished looks. Original garments, saved photography and construction observations for owner review.</p></div><div class="hero-aside"><span class="stop">REVIEW ONLY · IMAGE PRODUCTION STOPPED</span><p>Original garments lead every comparison. Saved studies are evidence, not design approval; rejected and unapproved V2 work is labelled separately.</p><p>Source checkpoint <a href="https://github.com/soufianeaberbach-sudo/portfolio/tree/{BASE}">{BASE[:12]}</a>. Public Portfolio unchanged.</p><div class="tools"><button class="plain-button" data-print>Print / save as PDF</button><a href="#owner-handoff" style="font-size:13px">Owner decision handoff ↓</a></div></div></section><details class="reading-guide"><summary>How to read this board · evidence, design quality and casting</summary><div class="legend"><div><b>Observed versus inferred</b><p>Construction notes distinguish visible features from plausible textile interpretation. Knit, woven, fibre and performance claims remain qualified where a photograph cannot establish them.</p></div><div><b>Photography versus design quality</b><p>17 saved generated views are shown: 8 V1 studies, 6 owner-rejected V2 views and 3 unapproved V2 views. One additional pre-stop output is unreviewed. None is a new approval.</p></div><div><b>Category and casting</b><p>Fashion beachwear, compelling eveningwear and relevant activewear retain their own design language. Casting follows garment fit and campaign suitability, with no arbitrary age prescription.</p></div></div></details></div><div class="nav-shell"><div class="wrap"><nav aria-label="Nine-look review index">{nav}</nav></div></div><main class="wrap">''']
 for i,look in enumerate(LOOKS,1):
  n=look['notes'];sid=look['sourceIdentity'];saved=look['saved'];empty=not saved;label=' '.join(v.title() for v in VIEWS if not any(x['label'].lower()==v for x in saved));proposal=n['recommendation'].startswith('PROPOSE')
  evidence=('<div class="photographs'+(' single' if len(saved)==1 else '')+'">'+''.join(figure(a) for a in saved)+'</div>') if saved else '<div class="empty"><strong>No saved V1 generated views.</strong><p>The historical photograph remains the actual garment evidence. No placeholder, fabricated Back or original-source substitution is counted as generated photography.</p></div>'
  parts.append(f'''<article class="look" id="{sid}" data-source-identity="{sid}"><header class="look-head"><span class="index">{i:02d} / 09</span><div><h2>{esc(n['title'])}</h2><p class="identity">{sid} · {esc(n['category'])}</p></div><div class="recommendation {'proposal' if proposal else ''}">{esc(n['recommendation'])}<br><span style="font-size:9px;opacity:.85">Recommendation only · owner decision pending</span></div></header><div class="compare"><div><h3 class="column-title">01 / ORIGINAL GARMENT</h3>{figure(look['source'],True)}<p class="source-note">{'Genuine Front and Back source evidence is shown together, exactly as supplied.' if look['sourceViews']==2 else 'Single-view original. Unseen rear construction is not historically verified.'}</p></div><div class="evidence-column"><h3 class="column-title">02 / SAVED SOURCE-BASED PHOTOGRAPHY</h3><p class="column-note">V1 technical passes are preserved. Owner artistic approval is not recorded. Views absent from V1: {esc(label or 'none')}.</p>{evidence}<div class="reading"><h3>Design reading</h3><p>{esc(n['judgment'])}</p></div><div class="reading"><h3>Saved-view comparison</h3><p>{esc(n['savedReview'])}</p></div></div></div><div class="analysis"><div><h3>Construction &amp; silhouette</h3><p>{esc(n['construction'])}</p><p class="uncertainty"><strong>Unresolved evidence.</strong> {esc(n['uncertainty'])}</p></div><div><h3>Fabric &amp; expected drape</h3><p class="fabric-class">{esc(n['fabricClass'])}</p><p>{esc(n['fabric'])}</p><p>{esc(n['drape'])}</p></div><div><h3>Category, styling &amp; casting</h3><p>{esc(n['styling'])}</p><p>Adult professional casting should support this garment and its intended campaign. No new model is selected or authorised on this board.</p></div></div><div class="decision"><strong>OWNER REVIEW RECOMMENDATION</strong>{esc(n['decision'])}</div>''')
  if look['other']:
   rejected=look['ownerRejected'];parts.append(f'''<section class="secondary {'rejected' if rejected else ''}" aria-label="{'Rejected' if rejected else 'Unapproved'} V2 evidence"><h3>{'REJECTED — owner decision' if rejected else 'Unapproved V2 — archived direction'}</h3><p>{esc(n['v2Review'])}</p><div class="photographs">{''.join(figure(a) for a in look['other'])}</div></section>''')
  else:parts.append(f'<p class="no-v2">{esc(n["v2Review"])}</p>')
  parts.append('</article>')
 parts.append(f'''<section class="handoff" id="owner-handoff"><div><div class="eyebrow">Creative approval returns to the owner</div><h2>Decide the direction<br>before the next photograph.</h2><p>Six recommendations preserve the original design; two improve photography; one asks for an owner-defined activewear design brief before a proposal. These are professional review recommendations, not approvals or production instructions.</p><p>No new garment design, replacement photography or model casting has been created for this review.</p></div><div><ol><li>Confirm each original garment direction or request a separately developed design proposal.</li><li>Resolve unsupported rear details, strap routing, support, lining and material evidence.</li><li>Approve a category-specific campaign and casting brief before any future image request.</li><li>Keep Tide Panel and Forest Fold rejected. Keep other V2 and unreviewed work unapproved unless the owner explicitly decides otherwise.</li></ol><p><strong>Image production remains stopped. Public Portfolio mappings remain unchanged.</strong></p></div></section></main><footer class="wrap">Review based on repository files at {BASE}. All 27 image files are genuine saved sources/outputs, displayed proportionally; no new photography, retouching or garment alteration. Material and construction observations are provisional where source evidence is insufficient. {'Self-contained offline edition: image and font bytes are embedded.' if portable else 'Repository edition: image paths refer to the unchanged local source and native files.'}</footer><dialog aria-label="Full-size garment photograph"><div class="modal-inner"><div class="modal-bar"><span class="modal-title" aria-live="polite"></span><button data-prev aria-label="Previous photograph">← Previous</button><button data-next aria-label="Next photograph">Next →</button><button data-zoom aria-pressed="false">100% / detail</button><button data-close>Close ×</button></div><div class="modal-stage"><img alt="Selected review photograph"></div><div class="modal-meta"></div></div></dialog><script>{JS}</script></body></html>''')
